#![allow(unused)]
use vstd::vec::Vec;

verus! {

    /// Given a size `n`, returns a vector of length `n`
    /// whose every entry is exactly 1.
    fn ones(n: usize) -> Vec<i8>
        // no requires beyond 0 ≤ n (implicit for usize)
        ensures result.len() == n
        ensures forall |i: usize| i < n ==> result[i] == 1
        ensures forall |i: usize, j: usize| i < n && j < n ==> result[i] == result[j]
        ensures forall |i: usize| i < n ==> result[i] > 0
    {
        let mut v: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        // We'll build up `v` entry by entry, maintaining the following invariants:
        //   1) 0 ≤ i ≤ n
        //   2) v.len() == i
        //   3) forall j < i: v[j] == 1
        // We also give a decreases clause to show the loop terminates.
        while i < n
            invariant i <= n
            invariant v.len() == i
            invariant forall |j: usize| j < i ==> v[j] == 1
            decreases n - i
        {
            v.push(1);
            i += 1;
        }
        v
    }

}